import java.text.NumberFormat;
import java.util.Scanner;
public class JIfElseWages2
{
	public static void main (String[] args)
	{
		//Paso 1: Definir las variables que necesitamos para este programa
		final double RATE = 8.25; 
		final int STANDARD = 40; 
		final int WEEKEND_PAY_MIN = 30; 
		final int WEEKEND_PAY_MAX = 50; 
		double wage = 0.0;
		//Paso 2: Leer los datos de entrada
		Scanner scan = new Scanner (System.in);
		System.out.println("Ingrese el numero de horas que el empleado ha trabajado: ");
		int hours = scan.nextInt();
		System.out.println("Ingrese el numero de dias que el empleado ha trabajado durante los fines de semana: ");
		int noWeekendDays = scan.nextInt();
		scan.close();
		//Paso 3: Pagar horas extras a "tiempo y medio" de la tarifa regular
		if (hours > STANDARD) {
			wage = STANDARD * RATE + (hours-STANDARD) * (RATE * 1.5);
		} else {
			wage = hours * RATE;
		}
		//Paso 4: Tener en cuenta el pago extra por el trabajo durante los fines de semana
		if (noWeekendDays < 5) {
			wage += (noWeekendDays * WEEKEND_PAY_MIN);
		} else {
			wage += (noWeekendDays * WEEKEND_PAY_MAX);
		}
		//Paso 5: Imprimir el salario calculado
		NumberFormat fmt = NumberFormat.getCurrencyInstance();
		System.out.println("Salario: " + fmt.format(wage));
	}
}

